<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Scholarship;
use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Filament Shield policy for Scholarship. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:Scholarship" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class ScholarshipPolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:Scholarship" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:Scholarship');
    }

    /**
     * Determine whether the admin may view one Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "View:Scholarship" permission.
     */
    public function view(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('View:Scholarship');
    }

    /**
     * Determine whether the admin may create Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:Scholarship" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:Scholarship');
    }

    /**
     * Determine whether the admin may edit a Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "Update:Scholarship" permission.
     */
    public function update(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('Update:Scholarship');
    }

    /**
     * Determine whether the admin may delete one Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "Delete:Scholarship" permission.
     */
    public function delete(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('Delete:Scholarship');
    }

    /**
     * Determine whether the admin may bulk delete Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:Scholarship" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:Scholarship');
    }

    /**
     * Determine whether the admin may restore one soft-deleted Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "Restore:Scholarship" permission.
     */
    public function restore(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('Restore:Scholarship');
    }

    /**
     * Determine whether the admin may permanently delete one Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "ForceDelete:Scholarship" permission.
     */
    public function forceDelete(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('ForceDelete:Scholarship');
    }

    /**
     * Determine whether the admin may permanently bulk delete Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:Scholarship" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:Scholarship');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:Scholarship" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:Scholarship');
    }

    /**
     * Determine whether the admin may duplicate a Scholarship record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Scholarship  $scholarship  The record being authorized.
     * @return bool True when the admin holds the "Replicate:Scholarship" permission.
     */
    public function replicate(AuthUser $authUser, Scholarship $scholarship): bool
    {
        return $authUser->can('Replicate:Scholarship');
    }

    /**
     * Determine whether the admin may reorder Scholarship records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:Scholarship" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:Scholarship');
    }
}
